import requests

SAMPLE = {
    'total_count': 4567890,
    'items': [
        {'full_name': 'TheAlgorithms/Python', 'stargazers_count': 187432,
         'description': 'All Algorithms implemented in Python'},
    ],
}


def fetch_repos(count=10, page=1):
    response = requests.get(
        'https://api.github.com/search/repositories',
        params={
            'q': 'language:python',
            'sort': 'stars',
            'order': 'desc',
            'per_page': count,
            'page': page,
        },
        headers={'Accept': 'application/vnd.github.v3+json'},
        timeout=10,
    )
    response.raise_for_status()
    return response.json()


def get_top_python_repos(count=10):
    try:
        data = fetch_repos(count)
    except Exception:
        # Timeout, HTTP error, or no network (sandbox): use a bundled sample
        data = SAMPLE

    print(f'Found {data["total_count"]:,} Python repos\n')
    for i, repo in enumerate(data['items'][:count], 1):
        print(f'{i}. {repo["full_name"]}')
        print(f'   Stars: {repo["stargazers_count"]:,}')
        print(f'   {repo["description"][:80] if repo["description"] else "No description"}')
    print('...')


get_top_python_repos()
